UPDATE pack_content.brand
SET narrative_json = $narrative${"version":1,"brandCode":"kittech","coreStatement":"Technology has value when it becomes a real operational system.","primaryAudience":["Founder","Ch\u1EE7 doanh nghi\u1EC7p","\u0110\u1ED9i ng\u0169 v\u1EADn h\u00E0nh","\u0110\u1ED1i t\u00E1c tri\u1EC3n khai","Ng\u01B0\u1EDDi \u0111ang x\u00E2y s\u1EA3n ph\u1EA9m s\u1ED1"],"secondaryAudience":[],"territories":[{"id":"kittech.core.building-real-systems","name":"Building Real Systems","type":"core","description":"C\u00E1ch x\u00E2y s\u1EA3n ph\u1EA9m, platform v\u00E0 h\u1EC7 th\u1ED1ng c\u00F3 th\u1EC3 v\u1EADn h\u00E0nh th\u1EADt.","whyItBelongs":"KIT k\u1EC3 chuy\u1EC7n t\u1EEB b\u00E0i to\u00E1n th\u1EF1c t\u1EBF th\u00E0nh h\u1EC7 th\u1ED1ng \u0111ang ch\u1EA1y, kh\u00F4ng k\u1EC3 AI k\u1EF3 di\u1EC7u.","audience":"Ng\u01B0\u1EDDi x\u00E2y v\u00E0 v\u1EADn h\u00E0nh h\u1EC7 th\u1ED1ng","examples":["Nh\u1EEFng quy\u1EBFt \u0111\u1ECBnh nh\u1ECF trong thi\u1EBFt k\u1EBF h\u1EC7 th\u1ED1ng c\u00F3 th\u1EC3 quy\u1EBFt \u0111\u1ECBnh kh\u1EA3 n\u0103ng v\u1EADn h\u00E0nh c\u1EE7a c\u1EA3 doanh nghi\u1EC7p."],"boundaries":["Kh\u00F4ng d\u1EEBng \u1EDF slogan c\u00F4ng ngh\u1EC7."],"priority":1},{"id":"kittech.core.operational-intelligence","name":"Operational Intelligence","type":"core","description":"Bi\u1EBFn d\u1EEF li\u1EC7u v\u00E0 quy tr\u00ECnh th\u00E0nh n\u0103ng l\u1EF1c v\u1EADn h\u00E0nh.","whyItBelongs":"D\u1EEF li\u1EC7u ch\u1EC9 c\u00F3 gi\u00E1 tr\u1ECB khi n\u00F3 \u0111\u1ED5i c\u00E1ch v\u1EADn h\u00E0nh.","audience":"\u0110\u1ED9i v\u1EADn h\u00E0nh","examples":["Quy tr\u00ECnh v\u00E0 d\u1EEF li\u1EC7u tr\u1EDF th\u00E0nh n\u0103ng l\u1EF1c v\u1EADn h\u00E0nh \u0111o \u0111\u01B0\u1EE3c."],"boundaries":["Kh\u00F4ng b\u00E1o c\u00E1o s\u1ED1 li\u1EC7u cho c\u00F3."],"priority":2},{"id":"kittech.core.ai-applied-to-real-work","name":"AI Applied to Real Work","type":"core","description":"AI \u0111\u01B0\u1EE3c \u0111\u01B0a v\u00E0o nh\u1EEFng c\u00F4ng vi\u1EC7c c\u1EE5